<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateVariable\Application\Service\Visibility;

use Psr\EventDispatcher\EventDispatcherInterface;

use Iterator;
use Throwable;

use Civi\Lughauth\Features\Access\Tenant\Application\Service\Visibility\TenantVisibilityService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\TemplateVariableRef;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\TemplateVariableAttributes;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\TemplateVariable;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableFilter;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableCursor;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableReadGateway;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableSlide;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateVariableVisibilityService
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly EventDispatcherInterface $dispatcher,
    private readonly TemplateVariableReadGateway $readGateway,
    private readonly TemplateVariableWriteGateway $writeGateway,
    private readonly TenantVisibilityService $tenantVisibilityService  ) {
  }

  public function prepareVisibleDataInList(TemplateVariable $content): TemplateVariableAttributes
  {
    return $this->prepareVisibleDataCallback($content, true);  }
  public function prepareVisibleData(TemplateVariable $content): TemplateVariableAttributes
  {
    return $this->prepareVisibleDataCallback($content, false);  }
  public function copyWithFixed(TemplateVariableAttributes $attributes, ?TemplateVariable $original = null): TemplateVariableAttributes
  {
    $this->logDebug("Copy with fixed for Template variable");
    $span = $this->startSpan("Copy with fixed for  Template variable");
    try {
      $visible = $this->visiblesReferences($attributes);
      $fixed = $this->fieldsToFix($original);
      foreach ($fixed as $field) {
        $visible->unset($field);
      }
      $result = $this->dispatcher->dispatch(new TemplateVariablePresetValues($attributes, $original));
      return $result->attributes;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }

  public function copyWithHidden(TemplateVariableAttributes $attributes, ?TemplateVariable $original = null): TemplateVariableAttributes
  {
    $this->logDebug("Copy with hidden for Template variable");
    $span = $this->startSpan("Copy with hidden for  Template variable");
    try {
      $hidden = $this->fieldsToHide($original);
      foreach ($hidden as $field) {
        $attributes->unset($field);
      }
      return $attributes;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }

  public function checkVisibility(Iterator|string|TemplateVariableRef $value): bool
  {
    $this->logDebug("Check visibility of an iterator for Template variable");
    $span = $this->startSpan("Check visibility of an iterator for  Template variable");
    try {
      if (is_string($value)) {
        return !!$this->retrieveVisibleForUpdate(new TemplateVariableRef( $value ) );
      } else if ($value instanceof TemplateVariableRef) {
        return !!$this->retrieveVisibleForUpdate($value );
      } else if ($value instanceof Iterator) {
        $ids = [];
        foreach ($value as $val) {
          $ids[] = $val->uid();
        }
        $filter = new TemplateVariableFilter(uids: $ids);
        return count($ids) == $this->countVisibles($filter);
      } else {        return false;      }
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function listVisibles(TemplateVariableFilter $filter, ?TemplateVariableCursor $cursor = null): TemplateVariableSlide
  {
    $this->logDebug("List visibles for Template variable");
    $span = $this->startSpan("List visibles for  Template variable");
    try {
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      $result = $this->readGateway->list($visibleFilter, $cursor);
      return $result->slide(function(TemplateVariable $item): bool {
        return $this->evaluatePostVisibility($item);
      });
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function countVisibles(TemplateVariableFilter $filter): int
  {
    $this->logDebug("Count visibles for Template variable");
    $span = $this->startSpan("Count visibles for  Template variable");
    try {
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      return $this->readGateway->count($visibleFilter);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function listVisiblesForUpdate(TemplateVariableFilter $filter, ?TemplateVariableCursor $cursor = null): TemplateVariableSlide
  {
    $this->logDebug("List visibles for update for Template variable");
    $span = $this->startSpan("List visibles for update for  Template variable");
    try {
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
      return $result->slide(function(TemplateVariable $item): bool {
        return $this->evaluatePostVisibility($item);
      });
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function countVisiblesForUpdate(TemplateVariableFilter $filter): int
  {
    $this->logDebug("Count visibles for update for Template variable");
    $span = $this->startSpan("Count visibles for update for  Template variable");
    try {
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      return $this->writeGateway->countForUpdate($visibleFilter);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function retrieveVisible(TemplateVariableRef $ref): ?TemplateVariable
  {
    $this->logDebug("Retrieve visible for Template variable");
    $span = $this->startSpan("Retrieve visible for  Template variable");
    try {
      $filter = new TemplateVariableFilter(uids: [$ref->uid()]);
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      if ($readed = $this->readGateway->retrieve($visibleFilter)) {
        return $this->evaluatePostVisibility($readed) ? $readed : null;
      } else {
        return null;
      }
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function retrieveVisibleForUpdate(TemplateVariableRef $ref): ?TemplateVariable
  {
    $this->logDebug("Retrieve visible for update for Template variable");
    $span = $this->startSpan("Retrieve visible for update for  Template variable");
    try {
      $filter = new TemplateVariableFilter(uids: [$ref->uid()]);
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      if( $readed = $this->writeGateway->retrieveForUpdate($visibleFilter) ) {
        return $this->evaluatePostVisibility($readed) ? $readed : null;
      } else {
        return null;
      }
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function fieldsToFix(?TemplateVariableRef $ref = null): array
  {
    $this->logDebug("Check fields to fix for Template variable");
    $span = $this->startSpan("Check fields for fix for Template variable");
    try {
      $result = $this->dispatcher->dispatch(new TemplateVariableCollectNonEditableFields(TemplateVariable::calculatedFields(), $ref));
      return array_values( array_unique( array_merge( $this->fieldsToHide($ref), $result->fields) ) );
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }

  public function fieldsToHide(?TemplateVariableRef $ref = null): array
  {
    $this->logDebug("Check fields to hide for Template variable");
    $span = $this->startSpan("Check fields to hide for  Template variable");
    try {
      $result = $this->dispatcher->dispatch(new TemplateVariableCollectNonVisibleFields([], $ref));
      return array_values( array_unique( $result->fields ) );
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }

  private function visiblesReferences(TemplateVariableAttributes $attributes): TemplateVariableAttributes
  {
    $this->logDebug("Check visibility of parent references for Template variable");
    $span = $this->startSpan("Check visibility of parent references for  Template variable");
    try {
      $tenant = $attributes->getTenant();      if( null !== $tenant && !$this->tenantVisibilityService->checkVisibility($tenant) ) {
        throw new NotFoundException("Unknown Tenant " . ( $tenant->uid() ?? 'no-id'));
      }
      return $attributes;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  private function applyPreVisibilityFilter(TemplateVariableFilter $filter): TemplateVariableFilter
  {
    $this->logDebug("Compose visibility filter for Template variable");
    $span = $this->startSpan("Compose visibility filter for  Template variable");
    try {
      $result = $this->dispatcher->dispatch(new TemplateVariableRestrictFilterToVisibility($filter));
      return $result->templateVariableFilter;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  private function evaluatePostVisibility(TemplateVariable $value): bool
  {
    $this->logDebug("Check if item is visible for Template variable");
    $span = $this->startSpan("Check if item is visible for  Template variable");
    try {
      $result = $this->dispatcher->dispatch(new TemplateVariableVisibilityCheck(true, $value));
      return $result->visible;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  private function prepareVisibleDataCallback(TemplateVariable $content, bool $inlist): TemplateVariableAttributes
  {
    $this->logDebug("Prepare hydration to visible data for Template variable");
    $span = $this->startSpan("Prepare hydration to visible data for Template variable");
    try {
      $attributes = $content->toAttributes();      $result = $this->dispatcher->dispatch(new TemplateVariableEnrichForView($content, $inlist, $attributes));
      return $result->getAttributes();
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
